from typing import Any, Dict
def _build_markdown(out:Dict[str,Any])->str:
    events=out.get("events") if isinstance(out.get("events"),dict) else {}; policy=out.get("policy") if isinstance(out.get("policy"),dict) else {}; signoff=out.get("signoff") if isinstance(out.get("signoff"),dict) else {}; checklist=out.get("checklist") if isinstance(out.get("checklist"),list) else []
    lines=[f"# M31 Weekly Health Summary ({out.get('week_start')} ~ {out.get('week_end')})","",f"- ok: **{bool(out.get('ok'))}**",f"- required_pass_total: **{int(out.get('required_pass_total') or 0)}**",f"- required_fail_total: **{int(out.get('required_fail_total') or 0)}**","","## Event Summary","",f"- total: **{int(events.get('total') or 0)}**",f"- error_total: **{int(events.get('error_total') or 0)}**",f"- error_rate: **{float(events.get('error_rate') or 0.0):.2%}**",f"- run_total: **{int(events.get('run_total') or 0)}**","","## Post-GoLive Policy Summary","",f"- policy_artifact_total: **{int(policy.get('found_total') or 0)}**",f"- normal_day_total: **{int(policy.get('normal_day_total') or 0)}**",f"- watch_day_total: **{int(policy.get('watch_day_total') or 0)}**",f"- incident_day_total: **{int(policy.get('incident_day_total') or 0)}**","","## Final Signoff Summary","",f"- signoff_artifact_total: **{int(signoff.get('found_total') or 0)}**",f"- approved_day_total: **{int(signoff.get('approved_day_total') or 0)}**",f"- hold_day_total: **{int(signoff.get('hold_day_total') or 0)}**","","## Checklist",""]
    for item in checklist: lines.append(f"- [{'x' if bool(item.get('passed')) else ' '}] {item.get('title')} | evidence={item.get('evidence')}")
    failures=out.get("failures") if isinstance(out.get("failures"),list) else []; lines += ["","## Failures",""] + ([f"- {x}" for x in failures] if failures else ["- (none)"]) + [""]
    return "\n".join(lines)
